create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text,phone text,role text default 'user' check(role in('user','staff','admin')));
create table if not exists public.donors(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id),full_name text not null,phone text not null,date_of_birth date,gender text,blood_group text not null,district text not null,upazila text,last_donation_date date,consent boolean not null default false,status text not null default 'pending',created_at timestamptz default now());
create table if not exists public.blood_requests(id uuid primary key default gen_random_uuid(),requester_user_id uuid references auth.users(id),patient_name text not null,phone text not null,blood_group text not null,units int not null check(units>0),hospital_name text,district text,needed_by timestamptz,urgency text default 'normal',status text default 'pending',created_at timestamptz default now());
create table if not exists public.blood_units(id uuid primary key default gen_random_uuid(),blood_group text not null,component text default 'Whole blood',quantity int not null default 1,expires_at date,storage_location text,status text default 'quarantine',created_at timestamptz default now());
create table if not exists public.workflow_records(id uuid primary key default gen_random_uuid(),module text not null,reference text not null,details text,status text default 'pending',created_by uuid references auth.users(id),created_at timestamptz default now());
create or replace function public.app_role() returns text language sql stable security definer set search_path=public as $$select coalesce((select role from profiles where id=auth.uid()),'user')$$;
create or replace function public.new_profile() returns trigger language plpgsql security definer set search_path=public as $$begin insert into profiles(id,display_name)values(new.id,coalesce(new.raw_user_meta_data->>'name',new.email))on conflict do nothing;return new;end$$;
drop trigger if exists auth_profile_insert on auth.users;create trigger auth_profile_insert after insert on auth.users for each row execute function public.new_profile();
alter table profiles enable row level security;alter table donors enable row level security;alter table blood_requests enable row level security;alter table blood_units enable row level security;alter table workflow_records enable row level security;
create policy profile_self_read on profiles for select to authenticated using(id=auth.uid() or app_role() in('staff','admin'));create policy profile_self_update on profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
create policy donors_insert_self on donors for insert to authenticated with check(user_id=auth.uid());create policy donors_read_self_staff on donors for select to authenticated using(user_id=auth.uid() or app_role() in('staff','admin'));create policy donors_update_staff on donors for update to authenticated using(app_role() in('staff','admin')) with check(app_role() in('staff','admin'));
create policy requests_insert_self on blood_requests for insert to authenticated with check(requester_user_id=auth.uid());create policy requests_read_self_staff on blood_requests for select to authenticated using(requester_user_id=auth.uid() or app_role() in('staff','admin'));create policy requests_update_staff on blood_requests for update to authenticated using(app_role() in('staff','admin')) with check(app_role() in('staff','admin'));
create policy stock_read_auth on blood_units for select to authenticated using(true);create policy stock_staff_manage on blood_units for all to authenticated using(app_role() in('staff','admin')) with check(app_role() in('staff','admin'));
create policy workflow_staff_read on workflow_records for select to authenticated using(app_role() in('staff','admin'));create policy workflow_staff_manage on workflow_records for all to authenticated using(app_role() in('staff','admin')) with check(app_role() in('staff','admin'));
grant select,insert,update on profiles,donors,blood_requests to authenticated;grant select,insert,update,delete on blood_units,workflow_records to authenticated;
